def split():
    """(entrenamiento, apartados): listas de (mensaje, respuesta)."""
    train=[];held=[]
    for reply,forms in INTENTS:
        for f in forms[:-2]:train.append((f,reply))
        for f in forms[-2:]:held.append((f,reply))
    return train,held
